[5705]={id=5705,name="Hmd. Salis. Steak",log_name="homemade salisbury steak",log_plural="homemade salisbury steaks",article=0,description="A homemade salisbury steak made\nfor you by your fellow. By modern\nconvention, it appears to be just\na smidgen overdone.\nAGI+1\nAccuracy+12% (Max. 80)\nAttack+10% (Max. 40)\nRanged Accuracy+12% (Max. 80)\nRanged Attack+10% (Max. 40)",category="usable",type=7,flags=30296,flag_names={"mog_garden","mail2account","noauction","canuse","cantradenpc","nosale","nodelivery","ex"},stack=1,targets=1,resource_id=200,cast_time=4,server_name="homemade_salisbury_steak",sort_name="hmd._salis._steak",server_type=5,ah=0,ah_name="none",base_sell=0,use_targets=1,activation=1,animation=28,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=1},
[5706]={id=5706,name="Hmd. Carbonara",log_name="dish of homemade carbonara",log_plural="dishes of homemade carbonara",article=0,description="Homemade carbonara made for you\nby your fellow. The noodles have\nbeen boiled to a perfect consistency\nthat adheres ever so deliciously\n\"to the teeth.\"\nCHR+1\nAccuracy+12% (Max. 80)\nAttack+10% (Max. 40)\nRanged Accuracy+12% (Max. 80)\nRanged Attack+10% (Max. 40)",category="usable",type=7,flags=30296,flag_names={"mog_garden","mail2account","noauction","canuse","cantradenpc","nosale","nodelivery","ex"},stack=1,targets=1,resource_id=200,cast_time=4,server_name="dish_of_homemade_carbonara",sort_name="hmd._carbonara",server_type=5,ah=0,ah_name="none",base_sell=0,use_targets=1,activation=1,animation=25,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
