[6149]={id=6149,name="Swing and Stab",log_name="copy of Swing and Stab",log_plural="copies of Swing and Stab",article=0,description="Ulla wrote this guide on sword wielding--from how to grip the hilt to tips on footwork--so others could follow in her footsteps. Adventurers note that reading it increases one's sword skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_swing_and_stab",sort_name="swing_and_stab",server_type=5,ah=46,ah_name="misc",base_sell=103,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6150]={id=6150,name="Mieuseloir's Diary",log_name="copy of Mieuseloir's diary",log_plural="copies of Mieuseloir's diary",article=0,description="An account penned by Mieuseloir B Enchelles of his encounters with the Gigas in Beaucedine Glacier. Adventurers note that reading it increases one's great sword skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_mieuseloirs_diary",sort_name="mieuseloirs_diary",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6151]={id=6151,name="Bull's Diary",log_name="copy of Striking Bull's diary",log_plural="copies of Striking Bull's diary",article=0,description="An account penned by Striking Bull during the Second Battle of Konschtat. It details the Republic's victory over King Raigegue the Lupine's San d'Orian army. Adventurers note that reading it increases one's axe skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_striking_bulls_diary",sort_name="bulls_diary",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6152]={id=6152,name="Death for Dim.",log_name="copy of Death for Dimwits",log_plural="copies of Death for Dimwits",article=0,description="A guide to the finer points of hacking everything in one's way to pieces with a two-handed axe, written by an anonymous individual. Adventurers note that reading it increases one's great axe skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_death_for_dimwits",sort_name="death_for_dim.",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6153]={id=6153,name="Ludwig's Report",log_name="copy of Ludwig's report",log_plural="copies of Ludwig's report",article=0,description="A report made by Ludwig Eichberg regarding the Battle of Grauberg. It details the constant changes in the position of the front line and the withdrawal of Republic troops. Adventurers note that reading it increases one's scythe skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_ludwigs_report",sort_name="ludwigs_report",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6154]={id=6154,name="Clash of Titans",log_name="copy of Clash of Titans",log_plural="copies of Clash of Titans",article=0,description="An article detailing the duel between  Yrvaulair S Cousseraux and Alphonimile M Aurchiat that became all the rage in San d'Oria after appearing in a popular newspaper. Adventurers note that reading it increases one's polearm skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_clash_of_titans",sort_name="clash_of_titans",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6155]={id=6155,name="Kagetora's Diary",log_name="copy of Kagetora's diary",log_plural="copies of Kagetora's diary",article=0,description="A diary written by Kagetora. In it he details each and every one of his ninety-eight victories and ninety-nine losses against Yomi. Adventurers note that reading it increases one's katana skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_kagetoras_diary",sort_name="kagetoras_diary",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6156]={id=6156,name="Noillurie's Log",log_name="copy of Noillurie's log",log_plural="copies of Noillurie's log",article=0,description="A record Noillurie kept of her personal experiences. The one that stands out the most is the battle with the colossal beast she undertook to prove herself to her order. Adventurers note that reading it increases one's great katana skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_noilluries_log",sort_name="noilluries_log",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6157]={id=6157,name="Ferreous's Diary",log_name="copy of Ferreous's diary",log_plural="copies of Ferreous's diary",article=0,description="A diary written by Ferreous Coffin that describes his encounters with Orcs in the north. So many were there that his war hammer became coated with a thick layer of blood after all was said and done. Adventurers note that reading it increases one's club skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_ferreouss_diary",sort_name="ferreouss_diary",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6158]={id=6158,name="K-P's Memoirs",log_name="copy of Kayeel-Payeel's memoirs",log_plural="copies of Kayeel-Payeel's memoirs",article=0,description="Memoirs penned by Kayeel-Payeel. They describe in particular detail the time he received Claustrum from the Warlock Warlord Robel-Akbel. Adventurers note that reading them increases one's staff skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_kayeel-payeels_memoirs",sort_name="k-ps_memoirs",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6159]={id=6159,name="Perih's Primer",log_name="copy of Perih's primer",log_plural="copies of Perih's primer",article=0,description="A guidebook Perih Vashai jotted down for the edification of new recruits. It discusses everything from the various ways of holding a bow to methods of judging distance. Adventurers note that reading it increases one's archery skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_perihs_primer",sort_name="perihs_primer",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6160]={id=6160,name="Barrels of Fun",log_name="copy of Barrels of Fun",log_plural="copies of Barrels of Fun",article=0,description="An educational text authored by Elivira Gogol. It discusses how to dismantle, clean, and reconstruct firearms in careful detail. Adventurers note that reading it increases one's marksmanship skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_barrels_of_fun",sort_name="barrels_of_fun",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6161]={id=6161,name="T.W. Enchiridion",log_name="throwing weapon enchiridion",log_plural="throwing weapon enchiridia",article=0,description="A guide to the finer points of hurling projectile objects at opponents, written by an anonymous individual. Adventurers note that reading it increases one's throwing skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="throwing_weapon_enchiridion",sort_name="t.w._enchiridion",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6162]={id=6162,name="Mikhe's Note",log_name="copy of Mikhe's note",log_plural="copies of Mikhe's note",article=0,description="A memo scrawled by Mikhe Aryohcha that matter-of-factly states, \"Just throw your guard up and it'll all work out.\" Adventurers note that reading it increases one's guarding skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_mikhes_note",sort_name="mikhes_note",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6163]={id=6163,name="Sonia's Diary",log_name="copy of Sonia's diary",log_plural="copies of Sonia's diary",article=0,description="A compilation of memories from Sonia. Of particular note are her observations on how to replicate the sheer brilliance of Annika Brilioth and the esoteric steps known as the Kriegstanz. Adventurers say that reading it increases their evasion skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_sonias_diary",sort_name="sonias_diary",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6164]={id=6164,name="The Successor",log_name="copy of The Successor",log_plural="copies of The Successor",article=0,description="An essay authored by Cerane I Virgaut, mainly concerning the night Perseus bequeathed unto her an exemplary shield. Adventurers note that reading it increases one's shield skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_the_successor",sort_name="the_successor",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6165]={id=6165,name="Kage. Journal",log_name="copy of Kagetora's journal",log_plural="copies of Kagetora's journal",article=0,description="A journal kept by Kagetora that delineates the extent to which he and Yomi lost themselves in their studies of the martial arts. Adventurers note that reading it increases one's parrying skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_kagetoras_journal",sort_name="kage._journal",server_type=5,ah=46,ah_name="misc",base_sell=103,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6166]={id=6166,name="Altana's Hymn",log_name="copy of Altana's Hymn",log_plural="copies of Altana's Hymn",article=0,description="A copy of Febrenard C Brunnaut's favorite read. The simple lyrics and enchanting meter were said to have soothed his soul. Adventurers note that reading it increases one's divine magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_altanas_hymn",sort_name="altanas_hymn",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6167]={id=6167,name="Coveffe Musings",log_name="copy of Coveffe Barrows musings",log_plural="copies of Coveffe Barrows musings",article=0,description="A collection of thoughts scribbled out by Ferreous Coffin on his visit to Coveffe Barrows. Adventurers note that reading it increases one's healing magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_coveffe_barrows_musings",sort_name="coveffe_musings",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6168]={id=6168,name="Aid for All",log_name="copy of Aid for All",log_plural="copies of Aid for All",article=0,description="A guide to the finer points of heightening the potential of one's compatriots, written by Rainemard. It also includes some tips on how to swing special swords. Adventurers note that reading it increases one's enhancing magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_aid_for_all",sort_name="aid_for_all",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6169]={id=6169,name="Inv. Report",log_name="investigative report",log_plural="investigative reports",article=1,description="A collection of observations made by Rainemard on a particular exploration. It goes into such detail on so much minutiae that many admit to never finishing it. Adventurers note that reading it increases one's enfeebling magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="investigative_report",sort_name="inv._report",server_type=5,ah=46,ah_name="misc",base_sell=103,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6170]={id=6170,name="Bounty List",log_name="bounty list",log_plural="bounty lists",article=0,description="A simple list of known criminals who are better off dead. Every single name is crossed out in Azima's handwriting. Adventurers note that reading it increases one's elemental magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="bounty_list",sort_name="bounty_list",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6171]={id=6171,name="Dark Deeds",log_name="copy of Dark Deeds",log_plural="copies of Dark Deeds",article=0,description="A guide to the finer points of insidious dark magic, as compiled by Azima. Proceeds from this tome have gone to fund her various purchases dealing with alchemical research. Adventurers note that reading it increases one's dark magic skill.",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="copy_of_dark_deeds",sort_name="dark_deeds",server_type=5,ah=46,ah_name="misc",base_sell=0,use_targets=1,activation=1,animation=117,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
