[6212]={id=6212,name="Marinara Slice +1",log_name="slice of marinara pizza +1",log_plural="slices of marinara pizza +1",article=0,description="Full stomachs ahead, Captain! You've cleaved off a heaping portion of the ultimate in seafood pizzas, simply loaded with succulent morsels of only the finest ocean delights.\nHP+25\nAccuracy+11% (Max. 58)\nAttack+21% (Max. 55)\n\"Undead Killer\"+5",category="usable",type=7,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="slice_of_marinara_pizza_+1",sort_name="marinara_slice_+1",server_type=5,ah=56,ah_name="breads_rice",base_sell=0,use_targets=1,activation=1,animation=28,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
