[6216]={id=6216,name="Pepp. Slice +1",log_name="slice of pepperoni pizza +1",log_plural="slices of pepperoni pizza +1",article=0,description="The width of this pepperoni slice, the consistency of its crust, the proportion of cheese to sauce. It's all here.\nHP+35 STR+2\nAccuracy+9% (Max. 11)\nAttack+10% (Max. 16)",category="usable",type=7,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=12,targets=1,resource_id=200,cast_time=4,server_name="slice_of_pepperoni_pizza_+1",sort_name="pepp._slice_+1",server_type=5,ah=56,ah_name="breads_rice",base_sell=0,use_targets=1,activation=1,animation=28,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
