[6219]={id=6219,name="Warthog Stewpot",log_name="warthog stewpot",log_plural="warthog stewpots",article=0,description="Centered around the unique taste of warthog meat, this Far Eastern delicacy is accented with a hefty helping of vegetables and other bounties of the forest.\nHP+10% (Max. 50)\nAttack+10% (Max. 20)\nRanged Attack+19% (Max. 40)\nHP recovered while healing +5",category="usable",type=7,flags=1580,flag_names={"mystery_box","mog_garden","inscribable","canuse","cantradenpc"},stack=1,targets=1,resource_id=200,cast_time=4,server_name="warthog_stewpot",sort_name="warthog_stewpot",server_type=5,ah=55,ah_name="soups",base_sell=0,use_targets=1,activation=1,animation=0,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
[6220]={id=6220,name="Prm. Wt. Stewpot",log_name="prime warthog stewpot",log_plural="prime warthog  stewpots",article=0,description="This rendition of one of the most iconic pieces of Vana'dielian cooking could barely get any better.\nHP+10% (Max. 75)\nSTR+3 MND+1\nAttack+10% (Max. 30)\nRanged Attack+19% (Max. 60)\nHP recovered while healing +7",category="usable",type=7,flags=1580,flag_names={"mystery_box","mog_garden","inscribable","canuse","cantradenpc"},stack=1,targets=1,resource_id=200,cast_time=4,server_name="prime_warthog_stewpot",sort_name="prm._wt._stewpot",server_type=5,ah=55,ah_name="soups",base_sell=0,use_targets=1,activation=1,animation=0,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
