[6257]={id=6257,name="Jungle Nectar",log_name="jar of jungle nectar",log_plural="jars of jungle nectar",article=0,description="This herbal beverage is made of juices\nsqueezed from the endless varieties of\nflora that cover Ulbuka. Contrary to\nits name, many state that it has a\nmouth-puckeringly, tongue-shrivelingly\nbitter flavor.\nMP+10 VIT-2 MND+3\nMagic Accuracy+1\n\"Magic Atk. Bonus\"+1",category="usable",type=1,flags=1548,flag_names={"mystery_box","mog_garden","canuse","cantradenpc"},stack=1,targets=1,resource_id=200,cast_time=4,server_name="jar_of_jungle_nectar",sort_name="jungle_nectar",server_type=5,ah=58,ah_name="drinks",base_sell=0,use_targets=1,activation=1,animation=0,animation_time=0,use_max_charges=0,use_delay_server=0,reuse_delay_server=0,use_aoe=0},
